import{_ as a,a as t,b as o,c as i,d as r,e as n,f as s,g as l,h as d}from"./chunks/wx20220320-163907.wyL2O1Gd.js";import{_ as c,o as h,c as p,a2 as u}from"./chunks/framework.CdjpmwdR.js";const x=JSON.parse('{"title":"Mesh‑Shaped Growth Path for Cloud‑Native Developers","description":"Using cloud‑native evolution and personal career practice to answer one question: how can developers build a transferable, amplifiable capability network instead of chasing isolated skills.","frontmatter":{"category":"mesh","date":"2022-03-01","title":"Mesh‑Shaped Growth Path for Cloud‑Native Developers","description":"Using cloud‑native evolution and personal career practice to answer one question: how can developers build a transferable, amplifiable capability network instead of chasing isolated skills.","tags":["mesh","架构设计","工程实践"],"image":"/blogs/assets/202203-mesh-shaped-cloud-native-developer/2022-03-13-22-37-47.jpeg"},"headers":[],"relativePath":"en/blogs/2022/202203-mesh-shaped-cloud-native-developer.md","filePath":"en/blogs/2022/202203-mesh-shaped-cloud-native-developer.md"}'),m={name:"en/blogs/2022/202203-mesh-shaped-cloud-native-developer.md"};function g(b,e,f,v,y,w){return h(),p("div",null,[...e[0]||(e[0]=[u('<h2 id="background-the-rise-of-cloud‐native" tabindex="-1">Background: The Rise of Cloud‑Native <a class="header-anchor" href="#background-the-rise-of-cloud‐native" aria-label="Permalink to &quot;Background: The Rise of Cloud‑Native&quot;">​</a></h2><p>Cloud computing has shifted from an optional tactic to core infrastructure for digital business. The question is no longer &quot;Should we go to the cloud?&quot; but &quot;How do we continuously deliver high‑quality applications on the cloud?&quot;</p><p>When traditional migration approaches hit their limits, a deeper question emerges: do cloud applications need a different set of design principles, collaboration models, and engineering practices compared with the on‑prem era?</p><p>Cloud‑native became mainstream in exactly this context. It is not just a tooling upgrade; it is a paradigm shift in how we build and operate software.</p><blockquote><p><a href="#cncf">Definition of Cloud‑Native</a> <br> Cloud native technologies empower organizations to build and run scalable applications in modern, dynamic environments such as public, private, and hybrid clouds. Containers, service meshes, microservices, immutable infrastructure, and declarative APIs exemplify this approach. <br> These techniques enable loosely coupled systems that are resilient, manageable, and observable. Combined with robust automation, they allow engineers to make high‑impact changes frequently and predictably with minimal toil.</p></blockquote><p>The key value of cloud‑native is decoupling: it separates business capabilities from cross‑cutting concerns such as deployment, elasticity, observability, and security, so teams can ship business value faster and more reliably.</p><p><img src="'+a+'" alt="business-logic-core"></p><p>In 2021 cloud‑native technology hit another wave of explosive adoption:</p><ul><li>Containers became the standard packaging format for cloud‑native apps, and Kubernetes became the de‑facto standard for running and orchestrating them.</li><li>SMI (Service Mesh Interface) and OAM (Open Application Model) attempt to define standards for the network and application layers.</li><li>Adoption has grown exponentially across industries and domains: from internet to factories, from web to IoT.</li><li>In China, leading internet companies have largely completed their cloud‑native transformations; Alibaba, Tencent and even CAICT have all published their cloud‑native blueprints (see <a href="#reports">#Links</a>).</li></ul><blockquote><p>&quot;Sir, the times have changed.&quot;</p></blockquote><h2 id="background-backend-developers-and-career-paths" tabindex="-1">Background: Backend Developers and Career Paths <a class="header-anchor" href="#background-backend-developers-and-career-paths" aria-label="Permalink to &quot;Background: Backend Developers and Career Paths&quot;">​</a></h2><p>As someone who started with the label &quot;Java / backend / developer&quot;, I have long been puzzled:</p><ul><li>Three years of Kotlin, but only a handful of truly high‑concurrency scenarios; my JVM knowledge is partial, my interview‑style theory even more so.</li><li>I can write React components and test Hooks logic; I have built CI/CD pipelines and Terraform automation.</li><li>I have done DevOps consulting, AWS solution design, and pre‑sales work…</li></ul><p>Yet most backend job descriptions still revolve around Spring, JVM, and Redis. These skills are important, but are they sufficient for handling the delivery complexity of the cloud‑native era? If a developer practices across business, platform, automation, and architecture, are they &quot;off the backend track&quot;?</p><h3 id="vertical-vs-horizontal-growth" tabindex="-1">Vertical vs Horizontal Growth <a class="header-anchor" href="#vertical-vs-horizontal-growth" aria-label="Permalink to &quot;Vertical vs Horizontal Growth&quot;">​</a></h3><p>Should developers grow horizontally — breadth‑first, reading widely? Or vertically — depth‑first, specializing in hard problems?</p><p>If we zoom out to the CTO horizon, a healthy trajectory mixes both breadth and depth at different stages. As your influence and authority broaden, communication and leadership become as important as technical skill (see <a href="#扩展如何定义架构师">Appendix: What Is an Architect</a>).</p><p><img src="'+t+'" alt="t-shaped"></p><p>Long‑term, you need both depth in your core domains and deliberate exploration into adjacent areas. Knowledge and skills are rarely isolated; each is often composed from more foundational pieces, and there are many links and couplings between them.</p><p>My conclusion: instead of stopping at a single T‑shape, your capability should evolve into a connectable, transferable mesh.</p><h4 id="the-trap-of-division-of-labor" tabindex="-1">The Trap of &quot;Division of Labor&quot; <a class="header-anchor" href="#the-trap-of-division-of-labor" aria-label="Permalink to &quot;The Trap of &quot;Division of Labor&quot;&quot;">​</a></h4><p>Division of labor creates a need for vertical specialization, but its nature is to maximize output in a narrow domain. Many so‑called &quot;specialties&quot; are in fact defined by capital: they bind workers to a narrow label so that labor can be traded as a commodity — for example, &quot;I need an SSH backend developer&quot;.</p><p>Once labor becomes a commodity, discounting and promotion logic naturally applies — this is the root of over‑competition and burnout.</p><p><img src="'+o+'" alt="scientist"></p><p>(Recommended) <a href="https://www.bilibili.com/video/BV18z4y1C7rX" target="_blank" rel="noreferrer">【硬核社会学】996、内卷、打工人：马克思为什么是对的（上）| 23:22</a></p><hr><h2 id="_00-preface" tabindex="-1">00. Preface <a class="header-anchor" href="#_00-preface" aria-label="Permalink to &quot;00. Preface&quot;">​</a></h2><p>When I first entered IT, I had a clear role model: the indie developer. Programming felt cool — combining different languages, frameworks, and services like Lego bricks to build interesting systems. Thoughtworks&#39; focus on technical excellence gave me many chances to try cutting‑edge technologies (Tech Radar).</p><p>After experimenting with different stacks, roles, and projects, my familiar domains and skills gradually extended beyond classic backend. But technical WeChat groups were still obsessed with Spring internals and JVM tuning, which made me doubt my direction. We were all doing CRUD, but why did our focus diverge so much?</p><p>After diving into cloud services and cloud‑native, the answer emerged for me: <strong>the development model has changed.</strong></p><ul><li>In the past, &quot;business and technology&quot; were hard to separate; when writing business logic you had to worry about many runtime, deployment, and operations concerns.</li><li>Now, cloud abstracts hardware and networking; cloud‑native abstracts technical components and development practices. Developers get simpler, more powerful tools.</li></ul><blockquote><p>&quot;It is like building a PC: pick parts on an e‑commerce site, follow a basic guide, and power on with one click&quot; — that is the cloud‑native development model.</p></blockquote><h2 id="_01-development-in-the-cloud‐native-era" tabindex="-1">01. Development in the Cloud‑Native Era <a class="header-anchor" href="#_01-development-in-the-cloud‐native-era" aria-label="Permalink to &quot;01. Development in the Cloud‑Native Era&quot;">​</a></h2><p>&quot;Abstraction — the essence of programming — is about distilling the problem domain and the solution domain.&quot; &quot;Encapsulation, inheritance, polymorphism — not just OO features, but the direction of technological progress.&quot;</p><h3 id="technical-descent" tabindex="-1">Technical Descent <a class="header-anchor" href="#technical-descent" aria-label="Permalink to &quot;Technical Descent&quot;">​</a></h3><p>Cloud computing sits above hardware and traditional software, providing a higher‑level abstraction layer. As certain problem domains get solved well, their solution space is packaged and productized into cloud services.</p><p>The more domains we industrialize, the richer our toolset becomes, and the easier it is to solve new problems on top.</p><p>Before the cloud era we built GUIs and backends with Java and Python, structured by procedural or OO thinking. In the cloud era we compose containers, serverless, and IaC.</p><p>Technical descent drives infrastructure shifts; infrastructure shifts drive industry upgrades.</p><h3 id="spiral-ascent" tabindex="-1">Spiral Ascent <a class="header-anchor" href="#spiral-ascent" aria-label="Permalink to &quot;Spiral Ascent&quot;">​</a></h3><p>&quot;Spiral ascent&quot; nicely describes how history and technology progress.</p><p>From history we know how electricity and the internal combustion engine enabled consumer electronics, computers, and cars, which in turn changed society. Today, software repeats the pattern. Cloud‑driven technical descent is triggering a cascade of higher‑level innovation.</p><p>Once upon a time you had to dig through docs to install a database, configure IPs, and set up replication. Now there are dozens of database vendors, many with subscription‑based cloud offerings. Ideas that used to live only in imagination are now mainstream:</p><ul><li>Abstractions for business: low‑code / no‑code</li><li>Abstractions for programming: BA with AI developer autopilot</li><li>Abstractions for architecture: Architecture as a Service (AaaS)</li></ul><p>Take Tencent Mini Programs: they are fully integrated with Tencent Cloud. You can use the IDE to develop, deploy, and operate cloud functions and storage without ever logging into the cloud console — truly &quot;one person, one army&quot;.</p><h3 id="staying-stable-amid-change" tabindex="-1">Staying Stable Amid Change <a class="header-anchor" href="#staying-stable-amid-change" aria-label="Permalink to &quot;Staying Stable Amid Change&quot;">​</a></h3><p>With such rapid change, how do developers keep up?</p><blockquote><p>&quot;Master math, physics, and chemistry; then you can go anywhere.&quot;</p></blockquote><p>Math, physics, and chemistry capture how the world works. In computing we have similar &quot;laws of nature&quot;: algorithms, CPU architecture, pipelines, consensus protocols, and so on.</p><p>&quot;Using AWS MQ for async messaging&quot; and &quot;CPU DMA talking to devices asynchronously&quot; are both instances of async IO in different layers.</p><p>So although I dislike rote interview drills, I still believe algorithms and computer architecture are fundamentals every developer should understand. As old technologies sink and new ones spiral upward, these laws sustain your learning and adaptation capacity.</p><h2 id="_10-developers-in-the-cloud‐native-era" tabindex="-1">10. Developers in the Cloud‑Native Era <a class="header-anchor" href="#_10-developers-in-the-cloud‐native-era" aria-label="Permalink to &quot;10. Developers in the Cloud‑Native Era&quot;">​</a></h2><p>In a narrow sense, a &quot;cloud‑native developer&quot; is someone who builds cloud‑native infrastructure: containers, CI/CD, cloud services, etc. They work in known problem domains, shaping reusable solutions and providing them as services — working on the <em>known</em> (for example, solution architects in cloud vendors).</p><p>But cloud‑native ultimately serves <em>business applications</em>. Before proposing solutions, you must clarify the problem domain: understand the business, commercial logic, and organizational context, design appropriate applications, and then choose cloud‑native options to support them.</p><p>In a broader sense, a cloud‑native developer is someone who understands cloud‑native concepts and technologies, and can apply them to increase individual, team, and organizational delivery efficiency — working on the <em>unknown</em> (for example, the opportunities at Thoughtworks).</p><h3 id="cloud‐native-developer-backend" tabindex="-1">&quot;Cloud‑Native Developer ≠ Backend&quot; <a class="header-anchor" href="#cloud‐native-developer-backend" aria-label="Permalink to &quot;&quot;Cloud‑Native Developer ≠ Backend&quot;&quot;">​</a></h3><p>&quot;Interviewing about nuclear bombs, screwing bolts at work&quot; captures many people&#39;s frustration with current hiring. But even if you master &quot;nuclear&quot; skills, do they actually make your daily delivery that much better? Maybe optimizing how to screw the bolts — improving boring day‑to‑day processes — matters more.</p><p>With cloud and cloud‑native, many previously &quot;advanced&quot; techniques are now basic services. As infrastructure standardizes, backend work shifts from &quot;server development&quot; to &quot;server‑side business development&quot;.</p><h3 id="cloud‐native-developer-devops" tabindex="-1">&quot;Cloud‑Native Developer ≠ DevOps&quot; <a class="header-anchor" href="#cloud‐native-developer-devops" aria-label="Permalink to &quot;&quot;Cloud‑Native Developer ≠ DevOps&quot;&quot;">​</a></h3><p>DevOps and SRE culture are integral to cloud‑native, so you can see them as a subset. But when you look at microservices, you realize decomposition is not purely technical: organization, business, and domain all affect how you split services, which then shapes containers and runtime architecture.</p><p>A cloud‑native developer cannot exist in isolation from business context — &quot;Your company is not Alibaba; you probably do not need a middle platform.&quot; In many Chinese companies, DevOps roles tilt toward Ops, while infrastructure development is labeled &quot;engineering effectiveness&quot; or &quot;platform team&quot;.</p><h3 id="cloud‐native-developer-≈-full‐stack-engineer-≈-10x-developer-≈-architect" tabindex="-1">&quot;Cloud‑Native Developer ≈ Full‑Stack Engineer ≈ 10x Developer ≈ Architect&quot; <a class="header-anchor" href="#cloud‐native-developer-≈-full‐stack-engineer-≈-10x-developer-≈-architect" aria-label="Permalink to &quot;&quot;Cloud‑Native Developer ≈ Full‑Stack Engineer ≈ 10x Developer ≈ Architect&quot;&quot;">​</a></h3><p>If someone can effectively apply cloud‑native concepts and tools and adapt to this development model, they are essentially playing the architect role: seeing across dimensions and domains, choosing appropriate technologies and architectures to support evolving business.</p><p>With everyone typing on similar keyboards, doing ten times the individual work is hard. But a cloud‑native developer can leverage the stack to:</p><ul><li>Goal: improve team/project/organization efficiency (10x team) <ul><li>By: improving software delivery (10x developer)</li><li>By: improving organizational communication (10x catalyst)</li></ul></li><li>Outcome: a &quot;10x developer&quot; in effect</li></ul><p>A more accurate label is <strong>full‑spectrum engineer</strong>.</p><h2 id="_11-mesh‐shaped-growth-model" tabindex="-1">11. Mesh‑Shaped Growth Model <a class="header-anchor" href="#_11-mesh‐shaped-growth-model" aria-label="Permalink to &quot;11. Mesh‑Shaped Growth Model&quot;">​</a></h2><p>Across layers (OS, applications, distributed systems) and domains (mobile, backend, cloud), many technical principles repeat. Once you master a principle in one area, you can transfer it to others and deepen your understanding.</p><p>In the cloud‑native era, abstraction levels shift more dramatically (from single‑machine, multi‑threaded, stable to cloud, multi‑node, elastic). The CNCF Landscape changes daily. How do you enter a new domain quickly? How do you adopt a new technology?</p><p>&quot;Stay stable amid change&quot; — my view is that cloud‑native developers and architects should go beyond T or Π shapes. Solid fundamentals across several &quot;disciplines&quot; form the base; on top of that you build cross‑discipline, cross‑domain expertise and keep expanding.</p><p>Many physicists have strong math backgrounds and read philosophy. Different domains provide different lenses.</p><h3 id="like-a-mesh" tabindex="-1">Like a Mesh <a class="header-anchor" href="#like-a-mesh" aria-label="Permalink to &quot;Like a Mesh&quot;">​</a></h3><p>Skills are not just binary labels; careers should not have only one direction. Your knowledge and abilities should form a mesh, where each node connects to others:</p><ul><li>Multiple skills stack as buffs, multiplying impact</li><li>Skills reinforce each other and deepen understanding</li><li>You learn new skills and domains by mapping them onto existing ones (like matching tiles in a puzzle game)</li><li>By expanding boundaries and strengthening the core, you change your position in the network (the &quot;mesh center&quot;)</li><li>Try everything</li></ul><p><img src="'+i+'" alt="skill-mesh"></p><h2 id="n-summary-looking-ahead" tabindex="-1">N. Summary: Looking Ahead <a class="header-anchor" href="#n-summary-looking-ahead" aria-label="Permalink to &quot;N. Summary: Looking Ahead&quot;">​</a></h2><p>&quot;Mesh‑Shaped + Cloud‑Native = a different career path&quot;</p><h3 id="cloud‐native-developer" tabindex="-1">Cloud‑Native Developer <a class="header-anchor" href="#cloud‐native-developer" aria-label="Permalink to &quot;Cloud‑Native Developer&quot;">​</a></h3><blockquote><p>The higher the gear ratio in a gearbox, the larger the torque it can deliver, and the faster the car can run. Gears implement leverage: with a small gear driving a large gear, you reduce speed and amplify torque. <br> How can 36 kilograms of force move a one‑ton car? Without gears, you cannot. The gear ratio — the tooth count ratio between gears — defines how much speed you trade for torque.</p></blockquote><p><img src="'+r+'" alt="engine"></p><p>A cloud‑native developer is this gearbox: choosing appropriate gears to drive different levels of business demand.</p><blockquote><p>&quot;He used the drainage ditch to corner, and even floored it!&quot;</p></blockquote><h3 id="mesh‐shaped-developer" tabindex="-1">Mesh‑Shaped Developer <a class="header-anchor" href="#mesh‐shaped-developer" aria-label="Permalink to &quot;Mesh‑Shaped Developer&quot;">​</a></h3><p>A line I like from a Web 3.0 article:</p><blockquote><p>&quot;Only when individuals can build networks, can networks truly form around individuals.&quot;</p></blockquote><p>As you master more skills and build a larger capability mesh, people, events, and opportunities start to stick to that mesh. That is how you create more possibilities.</p><blockquote><p>&quot;Expand boundaries beyond the present.&quot;</p></blockquote><hr><h2 id="appendix-what-is-an-architect" tabindex="-1">Appendix: What Is an Architect <a class="header-anchor" href="#appendix-what-is-an-architect" aria-label="Permalink to &quot;Appendix: What Is an Architect&quot;">​</a></h2><h3 id="architect-expectations-vs-domain" tabindex="-1">Architect: Expectations vs Domain <a class="header-anchor" href="#architect-expectations-vs-domain" aria-label="Permalink to &quot;Architect: Expectations vs Domain&quot;">​</a></h3><p>Most developers have a small goal in mind: become an architect. To get there, we need a workable definition.</p><h4 id="software-architect" tabindex="-1">Software Architect <a class="header-anchor" href="#software-architect" aria-label="Permalink to &quot;Software Architect&quot;">​</a></h4><blockquote><p>A software architect is a software development expert who makes high‑level design choices and tries to enforce technical standards, including software coding standards, tools, and platforms.</p></blockquote><p>An older Wiki version (now changed) split Software Architects into three types:</p><p><img src="'+n+'" alt="wiki-type-of-architect"></p><p>This categorization reflects differences in <em>expectations</em> and responsibilities. Often people assume Enterprise &gt; Solution &gt; Application, but they are not simple subsets. They address different concerns along different dimensions. (For example, Senior Enterprise Architect, Head of Solution Architecture…)</p><h4 id="domain-architect" tabindex="-1">Domain Architect <a class="header-anchor" href="#domain-architect" aria-label="Permalink to &quot;Domain Architect&quot;">​</a></h4><p>If you classify architects by domain expertise, you get something like this:</p><p><img src="'+s+'" alt="domain-type-of-architect"></p><h3 id="developer-competency-vs-archetype" tabindex="-1">Developer: Competency vs Archetype <a class="header-anchor" href="#developer-competency-vs-archetype" aria-label="Permalink to &quot;Developer: Competency vs Archetype&quot;">​</a></h3><p>So is a Cloud Architect a Solution Architect or an Enterprise Architect? Across role expectations and domains, &quot;Cloud Architect&quot; is not a simple A‑is‑B relationship. Without a workable taxonomy, you cannot define responsibilities, so you cannot design a concrete growth path.</p><p>At Thoughtworks, the <a href="https://pathways.thoughtworks.net/" target="_blank" rel="noreferrer">Pathway</a> model helped me a lot during performance reviews:</p><ul><li>Role + grade summarize your job profile — what the company expects you to be able to do and deliver.</li><li>Archetypes describe your responsibilities along specific dimensions — your fit for particular roles.</li><li>Competencies are the building‑block capabilities: development, consulting, communication, and so on.</li></ul><p><img src="'+l+'" alt="archetype"></p><p>If you want to grow from Developer to Tech Lead, Pathway shows clearly which core competencies you need and which you lack.</p><p><img src="'+d+'" alt="archetype-path"></p><p>Organized into growth routes like this, your abilities naturally form a <strong>mesh</strong>.</p><h2 id="appendix-knowledge-management" tabindex="-1">Appendix: Knowledge Management <a class="header-anchor" href="#appendix-knowledge-management" aria-label="Permalink to &quot;Appendix: Knowledge Management&quot;">​</a></h2><p>For a long time I used Typora + Trello for tasks and knowledge. As my skill mesh expanded, these tools stopped scaling. When I wanted to map out the mesh explicitly, I needed the knowledge structure behind it as well.</p><p>My TODO list and knowledge base also needed to be mesh‑shaped: discrete yet connected, so that they could support a mesh‑shaped skill system (Conway&#39;s Law?).</p><p>I eventually picked Logseq, and have already recommended it to many colleagues.</p><h3 id="logseq" tabindex="-1">&quot;Logseq!!!&quot; <a class="header-anchor" href="#logseq" aria-label="Permalink to &quot;&quot;Logseq!!!&quot;&quot;">​</a></h3><ul><li><a href="./202202-logseq-build-your-own-wiki">Logseq - Build your own Wiki</a></li><li><a href="./202212-logseq-customized-with-clojure-and-css">Logseq - Customized with Clojure and CSS</a></li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><h3 id="reports" tabindex="-1">Reports <a class="header-anchor" href="#reports" aria-label="Permalink to &quot;Reports&quot;">​</a></h3><ul><li>SlashData cloud‑native developer ecosystem | <a href="https://www.cncf.io/wp-content/uploads/2021/12/Q1-2021-State-of-Cloud-Native-development-FINAL.pdf" target="_blank" rel="noreferrer">The State of Cloud-Native Development 2021 Q1</a></li><li><a href="https://mp.weixin.qq.com/s?__biz=MjM5MDE0Mjc4MA==&amp;mid=2651106517&amp;idx=3&amp;sn=fc21f1a29d582fbb483d12f3b6178ac0&amp;chksm=bdb954868acedd90c14e12a9f5675685b560fa043a93b9550bc45406394101d5a7f0be8db044&amp;mpshare=1&amp;scene=1&amp;srcid=0214kerzprubNiE3J0be7HJA&amp;sharer_sharetime=1644822581245&amp;sharer_shareid=eff20db62f686469259d202fc0146a67#rd" target="_blank" rel="noreferrer">CNCF 2021 Survey (Chinese)</a> | <a href="https://www.cncf.io/reports/cncf-annual-survey-2021/" target="_blank" rel="noreferrer">CNCF Annual Survey 2021</a></li><li>Datadog containers | <a href="https://www.datadoghq.com/container-report/" target="_blank" rel="noreferrer">datadog-container-report</a></li><li>Datadog serverless | <a href="https://www.datadoghq.com/state-of-serverless/" target="_blank" rel="noreferrer">datadog-state-of-serverless</a></li><li><a href="https://segmentfault.com/a/1190000041422184" target="_blank" rel="noreferrer">Sysdig 2022 Cloud-Native Security and Usage Report (CN)</a> | <a href="https://sysdig.com/blog/2022-cloud-native-security-usage-report" target="_blank" rel="noreferrer">2022 Cloud-Native Security and Usage Report</a></li><li><a href="https://www.infoq.cn/article/S9wzvZU6BZMpMbkbvVQI" target="_blank" rel="noreferrer">Alibaba: Cloud‑Native Architecture in 2022</a></li><li><a href="https://www.infoq.cn/article/KxPztASa2Sfbwo4dZ4iF" target="_blank" rel="noreferrer">Cloud‑Native Trends to Watch in 2022 (Alibaba)</a></li><li><a href="https://segmentfault.com/a/1190000041371751" target="_blank" rel="noreferrer">Microsoft: Cloud‑Native Landing Trends 2022</a></li></ul><h3 id="cncf" tabindex="-1">CNCF <a class="header-anchor" href="#cncf" aria-label="Permalink to &quot;CNCF&quot;">​</a></h3><ul><li>CNCF (Cloud Native Computing Foundation) <ul><li><a href="https://github.com/cncf/foundation/blob/main/charter.md" target="_blank" rel="noreferrer">CNCF Foundation Charter</a></li></ul></li></ul><h3 id="architect" tabindex="-1">Architect <a class="header-anchor" href="#architect" aria-label="Permalink to &quot;Architect&quot;">​</a></h3><ul><li><a href="https://medium.com/@nvashanin/types-of-software-architects-aa03e359d192" target="_blank" rel="noreferrer">Types of Software Architects</a></li><li><a href="https://docs.google.com/presentation/d/1ia5GdebBrFZoSvXqM5hk9kUXYGaSYFUq46m8Uz8I7E4/edit" target="_blank" rel="noreferrer">Growth Paths at TW</a></li><li><a href="https://docs.google.com/presentation/d/1O24SOrZN9OTE3oGSZ53e4L2rPxKmt6gPJYroCm_uMzE/edit" target="_blank" rel="noreferrer">Development Career Paths</a></li></ul>',120)])])}const C=c(m,[["render",g]]);export{x as __pageData,C as default};
